(async()=>{const m = await import('/src/world/maps/puddlewick.js');
const L = m.puddlewickLayout();
window.__L = L; window.__W = {}; window.__SH = [];
const sleep = ms => new Promise(r=>setTimeout(r,ms)); window.__sleep = sleep;
window.__clear = async () => { for (let i=0;i<14;i++){ const d=__DQ.state().dialogue; if(!d||!d.open) break; __DQ.press('confirm'); await sleep(230);} const d=__DQ.state().dialogue; return !!(d&&d.open); };
window.__deg = (fx,fz,tx,tz) => Math.atan2(tx-fx, tz-fz)*180/Math.PI;
// hold Up in short chunks; stop the moment the map id changes
window.__push = async (camDeg, chunks) => {
  __DQ.cameraOrbit(camDeg); await sleep(560);
  const start = __DQ.state().map.id;
  for (let k=0;k<chunks;k++){
    await __clear();
    __DQ.hold('up', 420); await sleep(640);
    if (__DQ.state().map.id !== start) return __DQ.state().map.id;
  }
  await sleep(400);
  return __DQ.state().map.id;
};
window.__enter = async (door) => {
  if (__DQ.state().map.id !== 'puddlewick') { await __DQ.teleport('puddlewick'); await sleep(1300); }
  await __clear();
  const d = L.doors[door];
  __DQ.walkTo(d.x, d.z); await sleep(350);
  const fd = d.facing*180/Math.PI;
  let landed = await __push(fd+180, 6);
  const tries = [fd+200, fd+160, fd+180];
  for (let t=0; t<tries.length && landed==='puddlewick'; t++){
    __DQ.walkTo(d.x, d.z); await sleep(300);
    landed = await __push(tries[t], 6);
  }
  await sleep(900);
  const s = __DQ.state();
  return { door, landed: s.map.id, name: s.map.name, kind: s.map.kind, size: s.map.size, music: s.map.music,
    npcs: s.map.npcs, chests: s.map.chests, props: s.map.props, interactables: s.map.interactables,
    colliders: s.map.colliders, occluders: s.map.occluders, lines: s.map.lines,
    missingLines: s.map.missingLines, exits: s.map.exits, buildMs: s.map.buildMs,
    playerY: +s.player.y.toFixed(3), ground: s.player.ground, fps: s.fps,
    cam: s.field && s.field.camera ? { mode: s.field.camera.mode, pitch: s.field.camera.pitch, dist: s.field.camera.dist, orbit: s.field.camera.orbit } : null };
};
// search every container the treasure layer knows about, by walking up to it and facing it
window.__searchAll = async () => {
  const t = __DQ.state().treasure; if (!t) return { err: 'no treasure state' };
  const here = (t.here||[]).slice();
  const out = [];
  const cx = 0, cz = 0;
  for (const c of here) {
    await __clear();
    // stand 0.95 away from the container, on the side toward the room centre
    let dx = cx-c.x, dz = cz-c.z; const L2 = Math.hypot(dx,dz)||1; dx/=L2; dz/=L2;
    __DQ.walkTo(c.x + dx*0.95, c.z + dz*0.95); await sleep(220);
    const p = __DQ.state().player;
    __DQ.face(__deg(p.x,p.z,c.x,c.z)); await sleep(240);
    const r = __DQ.openNear(); await sleep(620);
    const d = __DQ.state().dialogue;
    out.push({ id: c.id, kind: c.kind, holds: c.holds||null, ok: !!(r&&r.ok), target: r&&r.target||null,
      reason: r&&r.reason||null, said: d&&d.open ? String(d.full||d.text||'').slice(0,70) : null });
    await __clear();
  }
  const t2 = __DQ.state().treasure;
  return { containers: t.containers, chests: t.chests, searchable: t.searchable, holding: t.holding,
    unplaced: t.unplaced, reached: out.filter(o=>o.ok).length, opened: t2.opened, found: t2.found, gold: t2.gold, list: out };
};
window.__leave = async () => {
  await __clear();
  const s0 = __DQ.state();
  const ex = (s0.field && s0.field.exits) || null;
  let landed = await __push(180, 7);
  if (landed !== 'puddlewick') { landed = await __push(150, 4); }
  if (landed !== 'puddlewick') { landed = await __push(210, 4); }
  await sleep(900);
  const s = __DQ.state();
  return { landed: s.map.id, name: s.map.name, at: [+s.player.x.toFixed(2), +s.player.z.toFixed(2)], exitsWas: ex };
};
return JSON.stringify({ doors: Object.keys(L.doors), nExits: L.exits.length });})()
